import { action, Flow, FlowArray, FlowObject, trigger, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

/**
 * Test case: Mixed scenario with both deterministic and non-deterministic complex objects
 * Expected behavior:
 * 1. address (deterministic): No $id/co_type_name in Fluent after round-trip
 * 2. contacts (non-deterministic): Has $id/co_type_name in Fluent after round-trip
 */
Flow(
    {
        $id: Now.ID['mixed_complex_object_flow'],
        name: 'Flow with Mixed Complex Objects',
        runAs: 'user',
        flowVariables: {
            // Deterministic complex object (no explicit $id or co_type_name)
            address: FlowObject({
                fields: {
                    street: StringColumn({
                        label: 'Street',
                    }),
                    city: StringColumn({
                        label: 'City',
                    }),
                    zipCode: StringColumn({
                        label: 'Zip Code',
                    }),
                },
                label: 'Address',
            }),
            // Non-deterministic complex object (explicit $id and co_type_name from UI)
            contacts: FlowArray({
                $id: 'ui_generated_contacts_id',
                co_type_name: 'UIGeneratedContactsList',
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({
                            label: 'Contact Name',
                        }),
                        phone: StringColumn({
                            label: 'Phone Number',
                        }),
                    },
                    label: 'Contact',
                }),
                childName: 'contact',
                label: 'Contacts List',
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['mixed_trigger'],
        },
        {
            table: 'incident',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['mixed_log_action'],
            },
            {
                log_level: 'info',
                log_message: `Address city: ${wfa.dataPill(_params.flowVariables.address.city, 'string')}`,
            }
        )
    }
)
